import { screen } from './shared.js';
export function renderResult(mission){return screen('Миссия завершена',`<div class="result-card"><div class="completion-badge" aria-hidden="true">✓</div><h2>${mission.title}</h2><p class="rule">${mission.slides[7].rule}</p><p>${mission.slides[7].discussion}</p><div class="button-stack"><button class="primary" data-action="replay" data-mission="${mission.id}">Повторить с другим выбором</button>${mission.id<10?`<button data-action="play" data-mission="${mission.id+1}">Следующая миссия</button>`:''}<button data-action="go" data-route="library">К списку миссий</button><button data-action="go" data-route="menu">Главное меню</button></div></div>`);}
